import type { RecommendationKind } from "@/features/proactive/types";
import type { Nudge } from "../proactive";

/**
 * Phase 7.1 adaptive Home: the section model. Client-safe types only.
 *
 * The application decides which sections exist, whether they show and in
 * what order (deterministic, see select.ts). Nothing here is generated by
 * an LLM. Every section says why it is showing.
 */

/** Adaptive sections answer "what do I do, and what first". Context sections answer "am I on track". */
export type SectionLayer = "adaptive" | "context";

/** Where an item comes from. Only "suggestion" is unsaved; the rest are real commitments. */
export type ItemSource = "calendar" | "task" | "suggestion";

export type DeadlineItem = {
  /** Task id, or the occurrence key for an event. */
  id: string;
  kind: "task" | "event";
  source: Exclude<ItemSource, "suggestion">;
  title: string;
  /** Local YYYY-MM-DD. */
  dateKey: string;
  /** Days from today (negative = overdue). */
  days: number;
  /** ISO instant used for ordering and the time label. */
  at: string;
  allDay: boolean;
  overdue: boolean;
  areaId: string | null;
  priority: "high" | "medium" | "low" | null;
};

/** Phase 7.2 Now / Next: the free window in front of the user and what fits it (engine, deterministic). */
export type NowData = {
  state: "free" | "session";
  until: string;
  minutes: number;
  message: string;
  /** The task that fits the window. May differ from the focus task when that one doesn't fit. */
  task: { taskId: string; title: string; fit: "whole" | "progress"; areaId: string | null } | null;
};

export type FocusData = {
  taskId: string;
  title: string;
  /** The engine's reason: "Due tomorrow", "Overdue since Mon". */
  why: string;
  estimatedMinutes: number | null;
  areaId: string | null;
  /** Free working time left today (Phase 4 scheduler, via the Phase 5 brief). */
  freeMinutesToday: number;
  /** Start of the next free stretch today, if any. */
  nextFreeAt: string | null;
  /** The brief's plan action label ("Plan my day"), when the engine has something to plan. Opens an approval card. */
  planLabel: string | null;
  /** Other focus tasks after this one (titles only). */
  then: { taskId: string; title: string; why: string }[];
  /** What to do with the time right now. Null when there is no usable window. */
  now: NowData | null;
  /** Overdue work, or work that won't fit before it's due: offer "I'm behind" (7.5). */
  behind?: boolean;
};

export type DeadlinesData = { items: DeadlineItem[]; more: number };

export type DayLoad = {
  dateKey: string;
  /** Timed calendar commitments, not counting Whitespace sessions. */
  commitmentMinutes: number;
  /** Whitespace work sessions already on the calendar. */
  sessionMinutes: number;
  /** Realistic free minutes for new work (engine capacity). */
  freeMinutes: number;
  /** Open tasks due that day. */
  due: number;
  /** The engine flagged this day as overloaded. */
  overloaded: boolean;
};

export type WorkloadData = {
  /** Engine warnings (overload, at risk). Each one is a suggestion: its buttons only ever propose. */
  warnings: Nudge[];
  /** Warnings that the conversation already raised: shown as facts, without repeating the offer. */
  coveredWarnings: { id: string; message: string }[];
  days: DayLoad[];
};

export type SuggestionsData = { items: Nudge[] };

export type OpenTimeData = {
  freeMinutes: number;
  /** Start of the next free stretch today. */
  from: string | null;
  /** Real things to use it on: active goals and undated tasks. Never invented. */
  ideas: { kind: "goal" | "task"; id: string; title: string; areaId: string | null }[];
};

export type WeekOutlookData = { days: DayLoad[] };

export type ComingUpData = { items: DeadlineItem[] };

export type ProgressData = {
  doneToday: number;
  doneThisWeek: number;
  recent: { id: string; title: string }[];
};

export type GoalsData = {
  goals: { id: string; title: string; progress: number | null; targetDate: string | null; areaId: string | null }[];
};

export type GettingStartedData = { aiConfigured: boolean };

export type SectionDataMap = {
  focus: FocusData;
  deadlines: DeadlinesData;
  workload: WorkloadData;
  suggestions: SuggestionsData;
  open_time: OpenTimeData;
  week_outlook: WeekOutlookData;
  progress: ProgressData;
  coming_up: ComingUpData;
  goals: GoalsData;
  getting_started: GettingStartedData;
};

export type SectionKind = keyof SectionDataMap;

type SectionOf<K extends SectionKind> = {
  /** Stable identifier (one section per kind on Home). */
  id: K;
  kind: K;
  layer: SectionLayer;
  /** 0-100. Decides whether it makes the cut and which section leads. Never decides position. */
  priority: number;
  /** Fixed position for this kind, so sections appear and disappear without swapping places. */
  slot: number;
  /** Why it is showing, in plain words ("2 deadlines in the next 3 days"). */
  reason: string;
  /** The most important section on the page right now gets gentle emphasis. */
  lead: boolean;
  data: SectionDataMap[K];
  /** Last relevant change, where known (ISO). */
  updatedAt: string | null;
};

export type HomeSection = { [K in SectionKind]: SectionOf<K> }[SectionKind];

export type HomeLayout = {
  /** Visible sections in render order (adaptive first, then context; each by slot). */
  sections: HomeSection[];
  /** True when nothing time-sensitive is going on. No warnings are shown on a calm day. */
  calm: boolean;
};

/** Kinds of recommendation the Workload section owns. */
export const WORKLOAD_KINDS: ReadonlySet<RecommendationKind> = new Set(["overload_day", "overload_week", "deadline_at_risk"]);
